arguments.command:
cd /tmp/sv-36d94f402fbf4d36bb36975a14ed1df4 && \
# Filter for actual function symbols (type T/t) near those addresses
nm --defined-only -n libmonosgen-2.0.so.dbg 2>/dev/null | grep -E ' [Tt] ' | awk -v addr1="2f4b20" -v addr2="2f4c84" -v addr3="2c1a40" '
  { if ($1 <= addr1) sym1=$3" (0x"$1")"; if ($1 <= addr2) sym2=$3" (0x"$1")"; if ($1 <= addr3) sym3=$3" (0x"$1")" }
  END { print "0x2f4b20 -> " sym1; print "0x2f4c84 -> " sym2; print "0x2c1a40 -> " sym3 }
'

